import markdown, re
t = open('run-log.md', encoding='utf-8').read()
svg = re.sub(r'<\?xml[^>]*\?>', '', open('graph.svg', encoding='utf-8').read())
body = markdown.markdown(t, extensions=['tables']).replace('<p><img alt="流程圖" src="graph.svg" /></p>', '<div class="g">' + svg + '</div>')
css = 'body{max-width:820px;margin:0 auto;padding:24px 16px 64px;font-family:"Noto Sans TC","PingFang TC","Microsoft JhengHei",system-ui,sans-serif;line-height:1.75;color:#1f2430;background:#f6f4ee}h1,h2{color:#1d5c63}a{color:#1d5c63}table{border-collapse:collapse;width:100%}td,th{border:1px solid #d9d3c4;padding:6px 8px;text-align:left;font-size:.92rem}.g svg{max-width:100%;height:auto;max-height:900px}.g{text-align:center;background:#fff;border:1px solid #d9d3c4;border-radius:8px;padding:8px}code{background:#ebe6d8;padding:1px 4px;border-radius:3px}.top{font-size:.9rem}@media(prefers-color-scheme:dark){body{background:#171a20;color:#ecebe6}h1,h2,a{color:#6cc4cc}td,th{border-color:#363c48}code{background:#2a2f39}}'
open('index.html', 'w', encoding='utf-8').write(f'<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>流程設計與執行紀錄｜高效學習法</title><style>{css}</style></head><body><p class="top"><a href="../index.html">首頁</a> / 流程與反思</p>{body}</body></html>')
